from pathlib import Path

p=Path('app/src/main/java/com/sakhtemanyar/MainActivity.java')
s=p.read_text(encoding='utf-8')
old='''    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode!=701||resultCode!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();io.submit(()->{try{java.io.InputStream in=getContentResolver().openInputStream(u);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[8192];int n,total=0;while((n=in.read(buf))!=-1){total+=n;if(total>10*1024*1024)throw new Exception("حجم فیش بیشتر از ۱۰ مگابایت است");out.write(buf,0,n);}in.close();String mime=getContentResolver().getType(u);if(mime==null)mime="application/octet-stream";JSONObject q=new JSONObject().put("action","upload_receipt").put("request_id",pendingRequestId).put("mime_type",mime).put("file_base64",Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP));JSONObject j=new JSONObject(post(q,session));if(j.has("error"))throw new Exception(j.getString("error"));runOnUiThread(()->toast("فیش با موفقیت ارسال شد؛ درخواست در انتظار تأیید مدیرکل است"));}catch(Exception e){runOnUiThread(()->toast(e.getMessage()==null?"خطا در ارسال فیش":e.getMessage()));}});}'''
new='''    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(resultCode!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();if(requestCode==701){io.submit(()->{try{java.io.InputStream in=getContentResolver().openInputStream(u);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[8192];int n,total=0;while((n=in.read(buf))!=-1){total+=n;if(total>10*1024*1024)throw new Exception("حجم فیش بیشتر از ۱۰ مگابایت است");out.write(buf,0,n);}if(in!=null)in.close();String mime=getContentResolver().getType(u);if(mime==null)mime="application/octet-stream";JSONObject q=new JSONObject().put("action","upload_receipt").put("request_id",pendingRequestId).put("mime_type",mime).put("file_base64",Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP));JSONObject j=new JSONObject(post(q,session));if(j.has("error"))throw new Exception(j.getString("error"));runOnUiThread(()->toast("فیش با موفقیت ارسال شد؛ درخواست در انتظار تأیید مدیرکل است"));}catch(Exception e){runOnUiThread(()->toast(e.getMessage()==null?"خطا در ارسال فیش":e.getMessage()));}});return;}if(requestCode==702){io.submit(()->{try{java.io.InputStream in=getContentResolver().openInputStream(u);Bitmap b=BitmapFactory.decodeStream(in);if(in!=null)in.close();if(b==null)throw new Exception("image");int max=1200,w=b.getWidth(),h=b.getHeight();if(Math.max(w,h)>max){float sc=Math.min((float)max/w,(float)max/h);b=Bitmap.createScaledBitmap(b,Math.max(1,(int)(w*sc)),Math.max(1,(int)(h*sc)),true);}java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,82,out);receiptData="data:image/jpeg;base64,"+Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP);runOnUiThread(()->{if(receiptButton!=null)receiptButton.setText("✓ فیش / عکس انتخاب شد");toast("عکس انتخاب شد و آماده ثبت است");});}catch(Exception e){runOnUiThread(()->toast("انتخاب عکس انجام نشد"));}});}}'''
if old not in s: raise SystemExit('expected receipt handler not found')
s=s.replace(old,new,1)
p.write_text(s,encoding='utf-8')
print('receipt result handling fixed')
